/**
 * Tool Catalog Manager — Discovers tools from project services and maintains an in-memory + DB cache.
 * Generated by Mindbricks Genesis Engine for the AgentHub service.
 *
 * Tool Sources: ["nutritionLibrary","mealTracker","nutritionAi"]
 * Refresh Interval: 5 minutes
 */
const axios = require("axios");

// In-memory tool cache: Map<toolName, { serviceName, description, parameters, serviceUrl }>
const toolCache = new Map();
let catalogInitialized = false;
let refreshTimer = null;

// Service URLs are set via environment variables: {SERVICE_NAME}_URL
// The AgentHub service has env vars for all other services set by setEnvironmentVariables()

/**
 * Get the base URL for a service from environment variables.
 */
function getServiceUrl(serviceName) {
  // Try specific env var first: e.g., TASKMANAGEMENT_SERVICE_URL
  const envKey = `${serviceName.toUpperCase().replace(/-/g, "_")}_SERVICE_URL`;
  if (process.env[envKey]) return process.env[envKey];

  // Try the generic inter-service pattern
  const svcUrl =
    process.env[`${serviceName}_URL`] ||
    process.env[`${serviceName.toUpperCase()}_URL`];
  if (svcUrl) return svcUrl;

  // Fallback: construct from SERVICE_URL pattern
  const baseUrl = process.env.SERVICE_URL;
  if (baseUrl) {
    // Replace the current service suffix with target service
    const parts = baseUrl.split("/");
    parts[parts.length - 1] = `${serviceName}-api`;
    return parts.join("/");
  }

  return null;
}

/**
 * Fetch tools from a single service via its /api/mcp-tools endpoint.
 */
async function fetchServiceTools(serviceName, serviceUrl) {
  try {
    const response = await axios.get(`${serviceUrl}/api/mcp-tools`, {
      timeout: 10000,
    });
    const tools = response.data?.tools || [];
    return tools.map((tool) => ({
      toolName: `${serviceName}:${tool.name}`,
      localName: tool.name,
      serviceName,
      description: tool.description || "",
      parameters: tool.inputSchema || tool.parameters || {},
      serviceUrl,
    }));
  } catch (err) {
    console.warn(
      `[ToolCatalog] Failed to fetch tools from ${serviceName}: ${err.message}`,
    );
    return [];
  }
}

/**
 * Discover tools from all configured tool sources.
 */
async function discoverAllTools() {
  const allTools = [];
  const toolSourceConfigs = [
    {
      excludeApis:
        "createFoodItem,updateFoodItem,deleteFoodItem,createPresetMeal,updatePresetMeal,deletePresetMeal,addPresetLine,deletePresetLine,setMacroTarget",
      includeApis:
        "getMyMacroTarget,getMyMacroTargetForLogging,listFoodItems,getFoodItem,getFoodItemForLogging,listPresetMeals,getPresetMeal,getPresetMealForLogging,listPresetLines",
      serviceName: "nutritionLibrary",
    },
    {
      excludeApis:
        "updateMealLog,deleteMealLog,updateMealLine,deleteMealLine,triggerDailyReminderCheck,triggerDailySummary",
      includeApis:
        "listMealLogs,getMealLog,listMealLines,getDailyProgress,getNutritionDay,listNutritionDays,getWeeklyAnalytics,getMonthlyAnalytics,createMealLog,createMealLine",
      serviceName: "mealTracker",
    },
    {
      excludeApis: "",
      includeApis:
        "parseMeal,askNutritionQuestion,getAiSession,listAiSessions,getAiCandidateMeal,listAiCandidateMeals,listAiGuidanceNotes,getAiGuidanceNote,confirmCandidateMeal,rejectCandidateMeal,updateAiCandidateLine",
      serviceName: "nutritionAi",
    },
  ];
  const discoverAll = toolSourceConfigs.some((s) => s.serviceName === "*");

  if (discoverAll) {
    // Discover from all services — scan environment for service URLs
    const serviceUrlPattern = /_SERVICE_URL$/;
    for (const [key, url] of Object.entries(process.env)) {
      if (!serviceUrlPattern.test(key) || !url) continue;
      const svcName = key
        .replace(/_SERVICE_URL$/, "")
        .toLowerCase()
        .replace(/_/g, "");
      if (svcName === "agenthub" || svcName === "auth") continue; // Skip self and auth
      const tools = await fetchServiceTools(svcName, url);
      allTools.push(...tools);
    }
  } else {
    // Discover from specific services
    for (const source of toolSourceConfigs) {
      const url = getServiceUrl(source.serviceName);
      if (!url) {
        console.warn(
          `[ToolCatalog] No URL found for service: ${source.serviceName}`,
        );
        continue;
      }
      let tools = await fetchServiceTools(source.serviceName, url);

      // Apply include/exclude filters
      if (source.includeApis && source.includeApis !== "*") {
        const includes = source.includeApis
          .split(",")
          .map((s) => s.trim().toLowerCase());
        tools = tools.filter((t) =>
          includes.includes(t.localName.toLowerCase()),
        );
      }
      if (source.excludeApis) {
        const excludes = source.excludeApis
          .split(",")
          .map((s) => s.trim().toLowerCase());
        tools = tools.filter(
          (t) => !excludes.includes(t.localName.toLowerCase()),
        );
      }

      allTools.push(...tools);
    }
  }

  return allTools;
}

/**
 * Refresh the tool catalog — updates both in-memory cache and DB.
 */
async function refreshCatalog() {
  try {
    console.log("[ToolCatalog] Refreshing tool catalog...");
    const tools = await discoverAllTools();

    // Update in-memory cache
    toolCache.clear();
    for (const tool of tools) {
      toolCache.set(tool.toolName, tool);
    }

    // Update DB (sys_toolCatalog) — upsert each tool
    try {
      const {
        upsertSys_toolCatalogByQuery,
        deleteSys_toolCatalogByQuery,
      } = require("dbLayer");
      const now = new Date();

      for (const tool of tools) {
        await upsertSys_toolCatalogByQuery(
          { toolName: tool.toolName },
          {
            toolName: tool.toolName,
            serviceName: tool.serviceName,
            description: tool.description,
            parameters: tool.parameters,
            lastRefreshed: now,
          },
        );
      }

      // Remove stale entries (tools that no longer exist)
      const activeNames = new Set(tools.map((t) => t.toolName));
      const { getSys_toolCatalogListByQuery } = require("dbLayer");
      const existing = await getSys_toolCatalogListByQuery({});
      for (const entry of existing?.items || existing || []) {
        if (!activeNames.has(entry.toolName)) {
          await deleteSys_toolCatalogByQuery({
            toolName: entry.toolName,
          }).catch(() => {});
        }
      }
    } catch (dbErr) {
      console.warn("[ToolCatalog] DB sync failed (non-fatal):", dbErr.message);
    }

    console.log(
      `[ToolCatalog] Refreshed: ${tools.length} tools from ${new Set(tools.map((t) => t.serviceName)).size} services`,
    );
    return tools;
  } catch (err) {
    console.error("[ToolCatalog] Refresh failed:", err.message);
    return [];
  }
}

/**
 * Initialize the tool catalog at service startup.
 */
async function initToolCatalog() {
  if (catalogInitialized) return;
  catalogInitialized = true;

  await refreshCatalog();
}

/**
 * Start periodic catalog refresh.
 */
function startCatalogRefresh(intervalMinutes) {
  const ms = (intervalMinutes || 5) * 60 * 1000;
  if (refreshTimer) clearInterval(refreshTimer);
  refreshTimer = setInterval(() => refreshCatalog(), ms);
  console.log(
    `[ToolCatalog] Periodic refresh started: every ${intervalMinutes || 5} minutes`,
  );
}

/**
 * Get tools for a specific agent based on its selectedTools list.
 * Returns an array of tool objects that can be registered in a ToolRegistry.
 */
function getToolsForAgent(selectedTools) {
  if (
    !selectedTools ||
    !Array.isArray(selectedTools) ||
    selectedTools.length === 0
  ) {
    return []; // No tools selected
  }

  const tools = [];
  for (const toolName of selectedTools) {
    const tool = toolCache.get(toolName);
    if (tool) {
      tools.push(tool);
    } else {
      console.warn(
        `[ToolCatalog] Selected tool not found in catalog: ${toolName}`,
      );
    }
  }
  return tools;
}

/**
 * Execute a remote tool by forwarding the call to the source service.
 */
async function callRemoteTool(toolName, args, headers = {}) {
  const tool = toolCache.get(toolName);
  if (!tool) {
    throw new Error(`Tool not found in catalog: ${toolName}`);
  }

  try {
    const response = await axios.post(
      `${tool.serviceUrl}/api/mcp-tools/call`,
      { tool: tool.localName, args },
      {
        headers: {
          "Content-Type": "application/json",
          ...headers,
        },
        timeout: 30000,
      },
    );
    return response.data;
  } catch (err) {
    throw new Error(
      `Remote tool call failed (${toolName}): ${err.response?.data?.error || err.message}`,
    );
  }
}

/**
 * Get the full catalog as an array (for listing APIs).
 */
function getCatalogArray() {
  return Array.from(toolCache.values());
}

module.exports = {
  initToolCatalog,
  startCatalogRefresh,
  refreshCatalog,
  getToolsForAgent,
  callRemoteTool,
  getCatalogArray,
  toolCache,
};
